// Generates every monitoring config from a client registry, so the registry is the only thing anyone edits.
// Keep the real registry in a PRIVATE repo whose deploy workflow calls the reusable ones here; they check it out and
// run this, so client data only ever exists inside a CI run — it is never committed to this public repo.
//   node scripts/sync.mjs --registry private/clients.yaml              write the generated files (deploy time)
//   node scripts/sync.mjs --registry clients.example.yaml --dry-run    validate + render only (public CI)
// Outputs:
//   uptime/packages/config/src/worker.ts   FlareWatch monitors (HTTP + domain registration)
//   uptime/packages/config/src/public.ts   FlareWatch status page: one group per client, private
//   usage/wrangler.generated.jsonc         usage collector: every client Cloudflare account, hourly, limit alerts on
//                                          (a separate file, so pulling upstream usage/ changes never conflicts)
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { parse } from "yaml";

const root = fileURLToPath(new URL("..", import.meta.url));
const read = (p) => readFileSync(root + p, "utf8");
// CI refuses any commit that contains this header (generated files hold client data).
const HEADER = "// GENERATED by scripts/sync.mjs from the client registry at deploy time. Do not commit.\n";
const STATUSES = new Set(["live", "unconfirmed", "paused"]);

export function load(text) {
  const doc = parse(text);
  const clients = doc?.clients;
  if (!Array.isArray(clients) || clients.length === 0) throw new Error("clients.yaml: `clients` must be a non-empty list");
  const ids = new Set();
  for (const c of clients) {
    if (!c?.id || !/^[a-z0-9-]+$/.test(c.id)) throw new Error(`clients.yaml: bad id ${JSON.stringify(c?.id)} (a-z, 0-9, -)`);
    if (ids.has(c.id)) throw new Error(`clients.yaml: duplicate id ${c.id}`);
    ids.add(c.id);
    if (!c.name) throw new Error(`clients.yaml: ${c.id} has no name`);
    if (!STATUSES.has(c.status)) throw new Error(`clients.yaml: ${c.id} status must be live | unconfirmed | paused`);
    const acct = c.cloudflare?.account_id;
    if (acct !== undefined && !/^[0-9a-f]{32}$/.test(acct)) throw new Error(`clients.yaml: ${c.id} cloudflare.account_id must be 32 hex chars`);
    const mids = new Set();
    for (const m of c.monitors ?? []) {
      if (!m?.id || !m.name || !/^https:\/\//.test(m.url ?? "")) throw new Error(`clients.yaml: ${c.id} monitor needs id, name and an https url`);
      if (mids.has(m.id)) throw new Error(`clients.yaml: ${c.id} has two monitors with id ${m.id}`);
      mids.add(m.id);
    }
    for (const [kind, u] of Object.entries(c.usage ?? {})) {
      const where = `clients.yaml: ${c.id} usage.${kind}`;
      if (!KINDS.includes(kind)) throw new Error(`${where}: unknown platform (${KINDS.join(" | ")})`);
      if (!/^[A-Z][A-Z0-9_]*$/.test(u?.token ?? "")) throw new Error(`${where}.token must name a key in the PROVIDER_TOKENS secret (A-Z, 0-9, _)`);
      if ((kind === "github" || kind === "vercel") && !u.account) throw new Error(`${where} needs account`);
      if (kind === "supabase" && !(Array.isArray(u.projects) && u.projects.length > 0 && u.projects.every((p) => /^[a-z0-9]+$/.test(p)))) {
        throw new Error(`${where}.projects must be a list of project refs`);
      }
    }
  }
  return clients;
}

// Platforms the usage collector checks besides Cloudflare (usage/src/providers.ts).
const KINDS = ["github", "resend", "supabase", "vercel"];
const PROVIDERS_CRON = "30 * * * *"; // = PROVIDERS_CRON in usage/src/run.ts

/** Other-platform targets of live clients, for PROVIDERS_JSON. Token *names* only; the tokens are a secret. */
export function providers(clients) {
  return live(clients).flatMap((c) =>
    Object.entries(c.usage ?? {}).map(([kind, u]) => ({
      id: c.id,
      client: c.name,
      kind,
      token: u.token,
      ...(u.account ? { account: String(u.account) } : {}),
      ...(u.org ? { org: true } : {}),
      ...(u.projects ? { projects: u.projects } : {}),
    })),
  );
}

export const DEFAULT_ORG = { name: "max-free-tier", timeZone: "UTC" };

/** Optional top-level `org: { name, url, timeZone }` — names the status page and sets alert times' zone. */
export function loadOrg(text) {
  const org = parse(text)?.org;
  if (org === undefined || org === null) return { ...DEFAULT_ORG };
  if (typeof org !== "object" || Array.isArray(org)) throw new Error("clients.yaml: `org` must be a mapping");
  if (org.url !== undefined && !/^https:\/\//.test(org.url)) throw new Error("clients.yaml: org.url must be an https URL");
  if (org.watchdog !== undefined && !/^https:\/\//.test(org.watchdog)) throw new Error("clients.yaml: org.watchdog must be an https URL");
  return { ...DEFAULT_ORG, ...org };
}

/**
 * Dead-man's switch outside Cloudflare: FlareWatch requests `org.watchdog` (e.g. a Healthchecks.io ping URL) every
 * minute, so the outside service alerts when those requests stop — FlareWatch or Cloudflare itself being down.
 */
export function watchdog(org) {
  if (!org.watchdog) return [];
  return [{ id: "watchdog", name: "Watchdog ping (outside Cloudflare)", method: "GET", target: org.watchdog, expectedCodes: [200], timeout: 10000 }];
}

const live = (clients) => clients.filter((c) => c.status === "live");

export function monitors(clients) {
  const out = [];
  for (const c of live(clients)) {
    for (const m of c.monitors ?? []) {
      out.push({
        id: `${c.id}_${m.id}`,
        name: `${c.name} · ${m.name}`,
        method: "GET",
        target: m.url,
        expectedCodes: m.expect ?? [200],
        ...(m.keyword ? { responseKeyword: m.keyword } : {}),
        timeout: 10000,
      });
    }
    for (const d of c.domains ?? []) {
      out.push({
        id: `${c.id}_domain_${d.replace(/[^a-z0-9]/gi, "_")}`,
        name: `${c.name} · ${d} registration`,
        method: "DOMAIN",
        target: d,
        domainExpiryDays: 30,
      });
    }
  }
  return out;
}

export function groups(clients) {
  const out = {};
  for (const m of monitors(clients)) {
    const client = live(clients).find((c) => m.id.startsWith(`${c.id}_`));
    (out[client.name] ??= []).push(m.id);
  }
  return out;
}

export function usageConfig(clients, upstreamWrangler) {
  const accounts = clients.filter((c) => c.status !== "paused" && c.cloudflare?.account_id);
  const compat = /"compatibility_date"\s*:\s*"([^"]+)"/.exec(upstreamWrangler)?.[1];
  if (!compat) throw new Error("usage/wrangler.jsonc: compatibility_date not found");
  const targets = providers(clients);
  return {
    $schema: "node_modules/wrangler/config-schema.json",
    name: "max-free-tier-usage",
    main: "src/index.ts",
    compatibility_date: compat,
    observability: { enabled: true, head_sampling_rate: 1 },
    // Hourly, so a limit is reported within the hour instead of within six. ~2 GraphQL calls per account per run.
    // Other platforms run at :30 in their own invocation (own subrequest budget), only when some client has them.
    triggers: { crons: targets.length > 0 ? ["0 * * * *", PROVIDERS_CRON] : ["0 * * * *"] },
    d1_databases: [
      {
        binding: "USAGE",
        database_name: "max-free-tier-usage",
        database_id: "__USAGE_D1_ID__", // injected by .github/workflows/usage.yml
        migrations_dir: "migrations",
      },
    ],
    vars: {
      CF_ACCOUNT_ID: accounts.map((c) => c.cloudflare.account_id).join(","),
      ACCOUNT_LABELS_JSON: JSON.stringify(Object.fromEntries(accounts.map((c) => [c.cloudflare.account_id, c.name]))),
      LIMIT_LEVELS: "50,80,95",
      THRESHOLDS_JSON: "",
      ...(targets.length > 0 ? { PROVIDERS_JSON: JSON.stringify(targets) } : {}),
    },
  };
}

export function render(clients, org = DEFAULT_ORG) {
  const ts = (name, type, value) =>
    `${HEADER}import type { ${type} } from '@flarewatch/shared';\n\nexport const ${name}: ${type} = ${JSON.stringify(value, null, 2)};\n`;
  return {
    "uptime/packages/config/src/worker.ts": ts("workerConfig", "WorkerConfig", {
      // Channels come from the FLAREWATCH_WEBHOOKS secret (built from TELEGRAM_* in .github/workflows/uptime.yml).
      // 5+ alerts in one run (e.g. a shared outage) arrive as one message.
      notification: { summaryAfter: 5, timeZone: org.timeZone },
      monitors: [...monitors(clients), ...watchdog(org)],
    }),
    "uptime/packages/config/src/public.ts": ts("pageConfig", "PageConfig", {
      title: `${org.name} — Status`,
      // Client domains are not public information; sign in to see the page.
      visibility: "private",
      ...(org.url ? { links: [{ label: org.name, link: org.url }] } : {}),
      group: { ...groups(clients), ...(org.watchdog ? { Monitoring: ["watchdog"] } : {}) },
    }),
    "usage/wrangler.generated.jsonc": `${HEADER}${biomeJson(usageConfig(clients, read("usage/wrangler.jsonc")))}\n`,
  };
}

// JSON in biome's style (usage/ lints its own folder with biome): objects expanded, arrays of primitives on one
// line when they fit in 100 columns. Keeps the generated file passing upstream's `pnpm lint` unchanged.
export function biomeJson(value, indent = "") {
  const inner = `${indent}  `;
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    const flat = value.every((v) => v === null || typeof v !== "object");
    const oneLine = `[${value.map((v) => JSON.stringify(v)).join(", ")}]`;
    if (flat && indent.length + oneLine.length <= 100) return oneLine;
    return `[\n${value.map((v) => inner + biomeJson(v, inner)).join(",\n")}\n${indent}]`;
  }
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value);
    if (entries.length === 0) return "{}";
    return `{\n${entries.map(([k, v]) => `${inner}${JSON.stringify(k)}: ${biomeJson(v, inner)}`).join(",\n")}\n${indent}}`;
  }
  return JSON.stringify(value);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const arg = (name) => {
    const i = process.argv.indexOf(name);
    return i > 0 ? process.argv[i + 1] : undefined;
  };
  const registry = arg("--registry");
  if (!registry) {
    console.error("usage: node scripts/sync.mjs --registry <path/to/clients.yaml> [--dry-run]");
    process.exit(2);
  }
  const text = readFileSync(registry, "utf8");
  const files = render(load(text), loadOrg(text));
  if (process.argv.includes("--dry-run")) {
    // Validate + render only (public CI uses the example registry). Never writes client data into the repo.
    console.log(`sync: ${registry} is valid; would write ${Object.keys(files).join(", ")}`);
  } else {
    for (const [path, content] of Object.entries(files)) writeFileSync(root + path, content);
    console.log(`sync: wrote ${Object.keys(files).length} files from ${registry} — deploy them, don't commit them`);
  }
}
